import app from 'flarum/forum/app';
import Link from 'flarum/common/components/Link';
import humanTime from 'flarum/common/helpers/humanTime';
import username from 'flarum/common/helpers/username';
import { art, count, ranked, scoreTile, stars } from './bits';
import { setting, t, tx } from '../util';

/** The name, cut to the admin's card length (MyBB product_name_length_card); the full name stays in the title. */
function shortName(name) {
  const max = Number(setting('card_name_max')) || 30;
  return name.length > max ? name.slice(0, max).trimEnd() + '…' : name;
}

/** A product card: picture, score tile, brand, name, stars, counts. `rankNo` adds the #1/#2/#3 medal. */
export function itemCard(item, rankNo) {
  const href = app.route('community-reviews.item', {
    id: item.urlId()
  });
  const isRanked = ranked(item);
  return m("article", {
    className: "CR-card",
    key: item.id()
  }, m(Link, {
    className: "CR-card-art",
    href: href,
    "aria-label": item.name()
  }, art(item), rankNo && rankNo <= 3 && isRanked ? m("span", {
    className: "CR-medal"
  }, m("i", {
    className: "fas fa-trophy",
    "aria-hidden": "true"
  }), " #", rankNo) : null, item.status() === 'pending' ? m("span", {
    className: "CR-medal CR-medal--pending"
  }, t('item.pending')) : null, scoreTile(item.rating(), 'CR-card-score', item.rating() !== null)), m("div", {
    className: "CR-card-body"
  }, item.brand() ? m("div", {
    className: "CR-card-brand"
  }, item.brand()) : null, m("h3", {
    className: "CR-card-name",
    title: item.name()
  }, m(Link, {
    href: href
  }, shortName(item.name()))), m("div", {
    className: "CR-card-rate"
  }, item.rating() !== null ? stars(item.rating()) : null, m("span", {
    className: "CR-muted"
  }, t('card.counts', {
    reviews: item.reviewCount(),
    comments: item.commentCount(),
    views: count(item.viewCount())
  }), item.rating() !== null && !isRanked ? ` · ${tx('card.not_ranked')}` : ''))));
}

/** A review in a list (latest reviews, a profile): the item's picture, its name, the score and a line of text. */
export function reviewRow(review) {
  const item = review.item();
  if (!item) return null;
  const user = review.user();
  const quote = review.title() || review.scores()?.[0]?.comment || '';
  return m(Link, {
    className: "CR-row",
    key: review.id(),
    href: app.route('community-reviews.item', {
      id: item.urlId()
    }) + `?review=${review.id()}`
  }, art(item), m("div", {
    className: "CR-row-main"
  }, m("div", {
    className: "CR-row-top"
  }, m("b", null, item.name()), scoreTile(review.rating(), 'CR-score--sm')), quote ? m("p", {
    className: "CR-row-quote"
  }, "\u201C", quote, "\u201D") : null, m("span", {
    className: "CR-muted"
  }, username(user || null), review.price() ? ` · ${tx('review.paid', {
    price: review.price()
  })}` : '', " \xB7 ", humanTime(review.createdAt()))));
}
flarum.reg.add('ernestdefoe-community-reviews', 'forum/ui/cards', { itemCard: itemCard,reviewRow: reviewRow, });