import app from 'flarum/forum/app';
import Component from 'flarum/common/Component';
import Button from 'flarum/common/components/Button';
import LoadingIndicator from 'flarum/common/components/LoadingIndicator';
import classList from 'flarum/common/utils/classList';
import { failed, setting, t } from '../util';
import { reviewRow } from './cards';
import { scoreTile } from './bits';
/**
 * A profile's Reviews tab: what the member wrote (MyBB's user widget) and, for a member of the Merchants group,
 * the reviews that tag them, with their average (MyBB's merchant page and widget).
 */
export default class UserReviews extends Component {
  tab = 'written';
  reviews = [];
  loading = true;
  more = false;
  summary = null;
  oninit(vnode) {
    super.oninit(vnode);
    if (this.isMerchant()) {
      this.tab = 'merchant';
      app.request({
        method: 'GET',
        url: `${app.forum.attribute('apiUrl')}/review-merchants/${this.attrs.user.id()}`
      }).then(r => this.summary = r.data.attributes).catch(failed).finally(() => m.redraw());
    }
    this.load(0);
  }
  isMerchant() {
    const group = Number(setting('merchant_group') || 0);
    return !!group && (this.attrs.user.groups() || []).some(g => g && Number(g.id()) === group);
  }
  load(offset) {
    this.loading = true;
    const filter = this.tab === 'merchant' ? {
      merchant: this.attrs.user.id()
    } : {
      user: this.attrs.user.id()
    };
    app.store.find('reviews', {
      filter,
      include: 'user,item,item.category',
      sort: '-createdAt',
      page: {
        offset,
        limit: 12,
        total: 0
      }
    }).then(list => {
      this.reviews = offset ? [...this.reviews, ...list] : [...list];
      this.more = !!list.payload?.links?.next;
    }).catch(failed).finally(() => {
      this.loading = false;
      m.redraw();
    });
  }
  view() {
    return m("div", {
      className: "CR-userreviews"
    }, this.isMerchant() && this.summary ? m("div", {
      className: "CR-merchant"
    }, scoreTile(this.summary.rating, 'CR-score--lg'), m("div", null, m("b", null, t('profile.merchant_rating')), m("div", {
      className: "CR-muted"
    }, t('profile.merchant_help', {
      count: this.summary.reviewCount,
      name: this.attrs.user.displayName()
    })))) : null, this.isMerchant() ? m("div", {
      className: "CR-chips",
      role: "tablist"
    }, ['merchant', 'written'].map(tab => m("button", {
      type: "button",
      role: "tab",
      "aria-selected": this.tab === tab ? 'true' : 'false',
      className: classList('CR-chip', this.tab === tab && 'is-active'),
      onclick: () => {
        this.tab = tab;
        this.load(0);
      }
    }, t(`profile.tab_${tab}`)))) : null, this.reviews.length ? m("div", {
      className: "CR-rows"
    }, this.reviews.map(reviewRow)) : this.loading ? null : m("p", {
      className: "CR-empty"
    }, t('profile.empty')), this.loading ? m(LoadingIndicator, null) : null, this.more && !this.loading ? m(Button, {
      className: "Button Button--block CR-more",
      onclick: () => this.load(this.reviews.length)
    }, t('page.load_more')) : null);
  }
}
flarum.reg.add('ernestdefoe-community-reviews', 'forum/ui/UserReviews', UserReviews);